/* clock(3) - determine processor time */
#include <stdio.h>
#include <time.h>

#define BILLION 1000000000L

// Function that simulates some work
void heavy_computation(void) {
    long i, j;
    long count = 0;
    // Perform a simple, CPU-intensive loop
    for (i = 0; i < BILLION; i++) {
        j = i * 2;
        if (j > 0) count++; // Prevent optimization from removing the loop entirely
    }
}

int main() {
    clock_t start_time, end_time;
    double cpu_time_used;

    // 1. Record the starting clock time
    start_time = clock();

    // Check for immediate error
    if (start_time == (clock_t)-1) {
        fprintf(stderr, "Error: Initial clock measurement failed.\n");
        return 1;
    }

    // 2. Execute the function to be timed
    printf("Starting heavy computation...\n");
    heavy_computation();
    printf("Computation finished.\n");

    // 3. Record the ending clock time
    end_time = clock();

    // 4. Calculate the duration and convert to seconds
    // CLOCKS_PER_SEC is the frequency of the clock
    cpu_time_used = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    printf("CPU time used by program: %.4f seconds\n", cpu_time_used);

    return 0;
}
